#include <iostream>
#include <string>
#include <sstream>

std::string markdownToHtml(const std::string& markdown) {
    // Create a string stream to hold the markdown text
    std::stringstream ss(markdown);

    // Convert the string stream to a string
    std::string html = ss.str();

    return html;
}

int main() {
    std::string markdown = "# Heading\n\nThis is a paragraph.";
    std::string html = markdownToHtml(markdown);
    std::cout << "<pre>" << html << "</pre>" << std::endl;
    return 0;
}
```

